CREATE TYPE "PartnerStatus" AS ENUM ('PENDING','ACTIVE','SUSPENDED','REJECTED');
CREATE TYPE "PartnerMemberRole" AS ENUM ('OWNER','MANAGER','MEMBER');
CREATE TYPE "CommissionStatus" AS ENUM ('PENDING','APPROVED','PAYABLE','PAID','VOID');
CREATE TYPE "PayoutStatus" AS ENUM ('REQUESTED','REVIEWING','APPROVED','PROCESSING','PAID','REJECTED','CANCELED');
CREATE TABLE "PartnerOrganization" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"status" "PartnerStatus" NOT NULL DEFAULT 'PENDING',"contactEmail" TEXT NOT NULL,"contactPhone" TEXT,"website" TEXT,"logoUrl" TEXT,"brandName" TEXT,"primaryColor" TEXT NOT NULL DEFAULT '#7A3045',"hideNgayDoiBrand" BOOLEAN NOT NULL DEFAULT false,"commissionRateBps" INTEGER NOT NULL DEFAULT 1000,"minimumPayout" INTEGER NOT NULL DEFAULT 500000,"approvedAt" TIMESTAMP(3),"approvedById" TEXT,"suspendedAt" TIMESTAMP(3),"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PartnerOrganization_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PartnerOrganization_slug_key" ON "PartnerOrganization"("slug"); CREATE INDEX "PartnerOrganization_status_createdAt_idx" ON "PartnerOrganization"("status","createdAt");
CREATE TABLE "PartnerMember" ("id" TEXT NOT NULL,"partnerId" TEXT NOT NULL,"userId" TEXT NOT NULL,"role" "PartnerMemberRole" NOT NULL DEFAULT 'MEMBER',"active" BOOLEAN NOT NULL DEFAULT true,"invitedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"joinedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PartnerMember_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PartnerMember_partnerId_userId_key" ON "PartnerMember"("partnerId","userId"); CREATE INDEX "PartnerMember_userId_active_idx" ON "PartnerMember"("userId","active"); CREATE INDEX "PartnerMember_partnerId_role_idx" ON "PartnerMember"("partnerId","role");
CREATE TABLE "PartnerClient" ("id" TEXT NOT NULL,"partnerId" TEXT NOT NULL,"customerId" TEXT NOT NULL,"weddingId" TEXT,"source" TEXT NOT NULL DEFAULT 'PARTNER_PORTAL',"externalRef" TEXT,"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PartnerClient_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PartnerClient_partnerId_customerId_weddingId_key" ON "PartnerClient"("partnerId","customerId","weddingId"); CREATE INDEX "PartnerClient_partnerId_createdAt_idx" ON "PartnerClient"("partnerId","createdAt"); CREATE INDEX "PartnerClient_customerId_idx" ON "PartnerClient"("customerId"); CREATE INDEX "PartnerClient_weddingId_idx" ON "PartnerClient"("weddingId");
CREATE TABLE "PartnerCommission" ("id" TEXT NOT NULL,"partnerId" TEXT NOT NULL,"orderId" TEXT,"customerId" TEXT,"weddingId" TEXT,"description" TEXT NOT NULL,"baseAmount" INTEGER NOT NULL,"rateBps" INTEGER NOT NULL,"commissionAmount" INTEGER NOT NULL,"status" "CommissionStatus" NOT NULL DEFAULT 'PENDING',"availableAt" TIMESTAMP(3),"approvedAt" TIMESTAMP(3),"paidAt" TIMESTAMP(3),"payoutId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PartnerCommission_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PartnerCommission_partnerId_orderId_key" ON "PartnerCommission"("partnerId","orderId"); CREATE INDEX "PartnerCommission_partnerId_status_createdAt_idx" ON "PartnerCommission"("partnerId","status","createdAt"); CREATE INDEX "PartnerCommission_payoutId_idx" ON "PartnerCommission"("payoutId");
CREATE TABLE "PartnerPayout" ("id" TEXT NOT NULL,"partnerId" TEXT NOT NULL,"requestedById" TEXT NOT NULL,"reviewedById" TEXT,"amount" INTEGER NOT NULL,"status" "PayoutStatus" NOT NULL DEFAULT 'REQUESTED',"bankName" TEXT NOT NULL,"accountName" TEXT NOT NULL,"accountNumberMasked" TEXT NOT NULL,"note" TEXT,"rejectionReason" TEXT,"requestedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"reviewedAt" TIMESTAMP(3),"paidAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PartnerPayout_pkey" PRIMARY KEY ("id"));
CREATE INDEX "PartnerPayout_partnerId_status_requestedAt_idx" ON "PartnerPayout"("partnerId","status","requestedAt");
